window.__rgjRes=null; window.__rgjErr=null;
(async () => { try {
  const urls = ['https://retroachievements.org/searchresults.php?q=Contra',
                'https://retroachievements.org/search?q=Contra',
                'https://retroachievements.org/gameList.php?system=7',
                'https://retroachievements.org/sitemap.xml'];
  const out = {};
  for (const u of urls) {
    try {
      const r = await fetch(u); const t = await r.text();
      out[u] = { status: r.status, len: t.length,
        gameCount: (t.match(/\/game\//g)||[]).length,
        hasContra: t.includes('Contra'),
        sitemapLocs: (t.match(/<loc>[^<]+<\/loc>/g)||[]).slice(0,5),
        sample: (t.match(/\/game\/\d+/g)||[]).slice(0,8) };
    } catch(e) { out[u] = { err: String(e.message) }; }
  }
  window.__rgjRes = JSON.stringify(out);
} catch(e){ window.__rgjErr = String(e && e.stack || e); } })();
